-- Populate transmission_units.maintenance_note for all 65 units.
-- reliability_note is untouched — only maintenance_note is set here.
-- Review before running. NOT executed against Supabase.

update transmission_units set maintenance_note = 'Single dry clutch is the main wear item (like a manual) - replacement roughly every 80-120k km, ~EUR 400-700. The Magneti Marelli hydraulic actuator/accumulator is the other failure point, ~EUR 400-900 if it goes. Gear oil ~every 90-120k km, ~EUR 60-100. On a high-km car budget for a clutch and possibly the actuator.' where code = 'Fiat Dualogic AMT';
update transmission_units set maintenance_note = 'Single dry clutch is the main wear item - replacement ~every 80-120k km, ~EUR 400-700. Clutch actuator/hydraulic unit is the other big cost, ~EUR 400-900. Gear oil ~every 90-120k km, ~EUR 60-100. Assume a clutch job on any high-km example.' where code = 'Opel Easytronic AMT';
update transmission_units set maintenance_note = 'Power-split hybrid transaxle, not a belt CVT: just a transaxle-fluid change ~every 60-100k km, ~EUR 80-150. No belt, filter or clutch to wear, so no big transmission bill. Any real cost sits in the hybrid battery/inverter, not the gearbox.' where code = 'Toyota Hybrid Synergy eCVT';
update transmission_units set maintenance_note = 'Treat CVT fluid as the critical service, not ''lifetime'': change ~every 60k km (~40-50k for hard/city use), ~EUR 120-250 with the correct fluid. Belt/chain or unit failure is usually uneconomical (~EUR 2,000-4,000+), so fluid discipline is the whole maintenance story.' where code = 'generic:?-speed CVT';
update transmission_units set maintenance_note = 'Chain-type CVT - keep the fluid fresh: change ~every 60k km (sooner if towing/hot use), ~EUR 150-300 with correct fluid. Not ''lifetime.'' Early valve-body/converter shudder is a repair rather than a service. A failed unit is uneconomical, so fluid is the priority.' where code = 'Subaru Lineartronic CVT';
update transmission_units set maintenance_note = 'CVT, so fluid is the key service - change ~every 60k km, ~EUR 120-250. Exact fluid spec/interval unconfirmed for this unit (see reliability note), so verify the correct fluid before servicing. Belt/chain or unit failure is uneconomical.' where code = 'Fiat/Alfa Multidrive S CVT';
update transmission_units set maintenance_note = 'Fluid interval matters more here than almost anywhere - change ~every 40-60k km without fail, ~EUR 150-280, and consider an auxiliary cooler for hard use. Overheated fluid kills these. A failed Xtronic is usually a replacement unit (~EUR 2,500-4,000+), so aggressive fluid changes are cheap insurance.' where code = 'Nissan Xtronic CVT (Jatco)';
update transmission_units set maintenance_note = 'Power-split hybrid, not a belt CVT: transaxle-fluid change ~every 60-100k km, ~EUR 80-150. No belt/clutch to wear. Big-ticket cost is hybrid electronics/battery, not the drive unit.' where code = 'Honda e:HEV eCVT';
update transmission_units set maintenance_note = 'Same power-split hybrid unit as the standard eCVT plus an electric rear axle: transaxle fluid ~every 60-100k km, ~EUR 80-150; rear e-axle is effectively maintenance-free. No belt/clutch. Costs sit in hybrid/AWD electronics, not the gearbox.' where code = 'Toyota Hybrid Synergy eCVT AWD-i';
update transmission_units set maintenance_note = 'Chain CVT - fluid + filter change ~every 60k km is essential, ~EUR 150-280. The chain and forward clutch pack are the expensive failures (slip/juddering); a failing unit is often uneconomical to rebuild (~EUR 2,000-3,500). Fresh fluid delays it but won''t save a worn one.' where code = 'Audi Multitronic CVT';
update transmission_units set maintenance_note = 'CVT fluid is the critical service, not ''lifetime'': ~every 60k km (sooner for city/hot use), ~EUR 120-230 with Honda-spec fluid. Belt/chain or unit failure is uneconomical, so keep the fluid fresh.' where code = 'Honda CVT';
update transmission_units set maintenance_note = 'CVT fluid ~every 60k km (sooner if used hard), ~EUR 120-230 with the correct Honda fluid; don''t treat it as lifetime. The launch-gear adds nothing to service. Unit failure is uneconomical, so fluid discipline is the whole game.' where code = 'Honda Direct Shift CVT';
update transmission_units set maintenance_note = 'Service to type: if WET-clutch, fluid + filter ~every 60k km (~EUR 150-260); if DRY-clutch, small gear-oil change ~every 60k (~EUR 100-160) and budget the clutch pack/mechatronic as the big item (~EUR 700-1,500). Confirm dry vs wet before quoting.' where code = 'generic:7-speed dct';
update transmission_units set maintenance_note = 'Service to type: if WET-clutch, fluid + filter ~every 60k km (~EUR 150-260); if DRY-clutch, small gear-oil change ~every 60k (~EUR 100-160) and budget the clutch pack/mechatronic as the big item (~EUR 700-1,500). Confirm dry vs wet before quoting.' where code = 'generic:6-speed dct';
update transmission_units set maintenance_note = 'Almost always wet-clutch at this size: fluid + filter ~every 60k km, ~EUR 150-280. Clutch pack is a high-km/abuse wear item (~EUR 900-1,500). Confirm the exact unit for fluid spec.' where code = 'generic:8-speed dct';
update transmission_units set maintenance_note = 'Dry-clutch DSG. Gear oil is small (~1.7 L) and badged ''lifetime,'' but change it ~every 60k km as cheap insurance, ~EUR 100-160. The mechatronic is the big-ticket failure (~EUR 900-1,500) and the dry clutch pack is a wear item (~EUR 700-1,200) - budget for one on a high-km/city car.' where code = 'VW DQ200';
update transmission_units set maintenance_note = 'Dry-clutch DCT. Gearbox oil ~every 60k km, ~EUR 100-160. The real cost is the clutch/actuator: clutch ~EUR 800-1,300, mechatronic/actuator ~EUR 700-1,200. Expect one on a high-km stop-go car.' where code = 'Renault EDC 7-speed (dry)';
update transmission_units set maintenance_note = 'No routine fluid service saves this one - it''s about the clutch and TCM. Clutch replacement ~EUR 700-1,200; TCM ~EUR 400-900; if the input-shaft seals are leaking onto the clutches, seal + clutch job ~EUR 900-1,500. On any DPS6 car, price in a clutch/TCM job unless there is fresh documented history.' where code = 'Ford PowerShift DPS6 (6-speed dry)';
update transmission_units set maintenance_note = 'Dry-clutch DCT. Gear oil ~every 60k km, ~EUR 100-160. Clutch and actuator are the costs: clutch ~EUR 800-1,300, actuator/mechatronic ~EUR 700-1,200. Assume a clutch on a high-km city car.' where code = 'Renault EDC 6-speed (dry)';
update transmission_units set maintenance_note = 'Wet-clutch PowerShift (6DCT450) - fluid + filter change ~every 60k km, ~EUR 150-250. Clutch pack is a high-km wear item, ~EUR 800-1,300. Far cheaper to keep than the dry DPS6; just keep the fluid on schedule.' where code = 'Ford PowerShift 7-speed';
update transmission_units set maintenance_note = 'Wet-clutch DSG - fluid + filter change ~every 60,000 km is essential, ~EUR 160-260. Clutch pack and (rarely) mechatronic are the only high-km items, clutch ~EUR 900-1,400. Keep the 60k interval and it stays reliable.' where code = 'VW DQ381';
update transmission_units set maintenance_note = 'Wet-clutch DSG - fluid + filter ~every 60,000 km is non-negotiable, ~EUR 150-250; neglect is what kills the mechatronic/clutch. Mechatronic ~EUR 800-1,300, clutch pack ~EUR 900-1,400 if needed at high km.' where code = 'VW DQ250';
update transmission_units set maintenance_note = 'Wet-clutch DSG (high-torque) - fluid + filter ~every 60,000 km, ~EUR 170-280 (larger fluid volume). Robust; clutch/mechatronic only at high km/abuse (~EUR 1,000-1,500). Just keep the interval.' where code = 'VW DQ500';
update transmission_units set maintenance_note = 'Wet-clutch performance transaxle - fluid + filter per schedule (~every 60-90k km or by track use), ~EUR 300-600 at a specialist. Clutch pack only wears under repeated launches/track (~EUR 1,500-3,000). No routine big-ticket item for road use.' where code = 'Mercedes-AMG 8-speed DCT';
update transmission_units set maintenance_note = 'Dog-clutch hybrid gearbox with no friction clutch to wear - mainly a fluid change per schedule (~every 60-90k km), ~EUR 120-220. Limited long-term data; keep to Renault''s intervals. Cost risk is hybrid electronics, not the gearbox.' where code = 'Renault E-TECH Multi-mode';
update transmission_units set maintenance_note = 'Wet-clutch DCT - fluid + filter change ~every 60-90k km, ~EUR 400-700 at Porsche/specialist (premium fluid + volume). Clutches only wear under sustained track/launch use (~EUR 2,000-3,500). Otherwise essentially service-only.' where code = 'Porsche PDK-7';
update transmission_units set maintenance_note = '9G-based with a wet start clutch instead of a converter - fluid + filter per schedule (~every 60-90k km), ~EUR 300-600. Start clutch wears only under hard repeated launches (~EUR 1,500-3,000). No chronic routine cost.' where code = 'Mercedes-AMG SpeedShift MCT 9-speed';
update transmission_units set maintenance_note = 'Wet-clutch DCT - fluid + filter ~every 60-90k km, ~EUR 400-700 at specialist. Very robust; clutches wear only under sustained abuse (~EUR 2,000-3,500). Service-only for normal use.' where code = 'Porsche PDK-8';
update transmission_units set maintenance_note = 'Dog-clutch hybrid drive, no friction clutch or converter to wear - fluid change per schedule (~every 60-90k km), ~EUR 120-220. Newer/low-volume, so follow Renault intervals. Any real cost is hybrid-system electronics, not the drive unit.' where code = 'Renault E-TECH Clutchless Auto';
update transmission_units set maintenance_note = 'Wet-clutch plug-in-hybrid DSG - fluid + filter ~every 60k km, ~EUR 160-280. Wet clutches are durable with no dry-clutch judder pattern. Follow VW''s PHEV service schedule.' where code = 'VW DQ400e';
update transmission_units set maintenance_note = 'Wet-clutch performance transaxle - fluid + filter per schedule (~every 60-90k km / track use), ~EUR 300-600. Clutch pack only under hard use (~EUR 1,500-3,000). Service-only otherwise.' where code = 'Mercedes-AMG DCT 7-speed (rear transaxle)';
update transmission_units set maintenance_note = 'Wet-clutch performance DCT - fluid + filter ~every 60k km (sooner for track), ~EUR 200-350. Clutch pack wears only under hard/track use (~EUR 1,200-2,000). Otherwise reliable and service-only.' where code = 'Hyundai N DCT 8-speed (wet)';
update transmission_units set maintenance_note = 'Gear oil change ~every 100-120k km (often called ''lifetime'' - a change is cheap insurance), ~EUR 60-120. The clutch is a condition-based wear item, not a scheduled service: ~EUR 400-900, or ~EUR 700-1,300 if it has a dual-mass flywheel. Otherwise nothing to schedule.' where code = 'generic:6-speed Manual';
update transmission_units set maintenance_note = 'Gear oil change ~every 100-120k km (often called ''lifetime'' - a change is cheap insurance), ~EUR 60-120. The clutch is a condition-based wear item, not a scheduled service: ~EUR 400-900, or ~EUR 700-1,300 with a dual-mass flywheel. Otherwise nothing to schedule.' where code = 'generic:5-speed Manual';
update transmission_units set maintenance_note = 'Gear oil ~every 100-120k km, ~EUR 60-110 (small unit). Clutch is a wear item: ~EUR 450-900, or ~EUR 700-1,300 with a dual-mass flywheel. No other scheduled gearbox service.' where code = 'VW MQ200';
update transmission_units set maintenance_note = 'Gear oil ~every 100-120k km, ~EUR 60-120. Clutch a wear item ~EUR 450-900 (~EUR 700-1,300 with DMF). Nothing else scheduled.' where code = 'VW MQ250';
update transmission_units set maintenance_note = 'Gear oil ~every 100-120k km, ~EUR 70-120. Clutch a wear item ~EUR 500-950 (~EUR 800-1,400 with DMF on torquier engines). Robust otherwise.' where code = 'VW MQ350';
update transmission_units set maintenance_note = 'Gear oil change ~every 100-120k km (often called ''lifetime'' - a change is cheap insurance), ~EUR 60-120. The clutch is a condition-based wear item, not a scheduled service: ~EUR 400-900, or ~EUR 700-1,300 with a dual-mass flywheel. Otherwise nothing to schedule.' where code = 'generic:7-speed Manual';
update transmission_units set maintenance_note = 'Gear oil ~every 100-120k km, ~EUR 60-110. Clutch a wear item ~EUR 400-800 (small-engine cars, often single-mass flywheel). Nothing else scheduled.' where code = 'VW MQ100';
update transmission_units set maintenance_note = 'Gear oil change ~every 100-120k km (often called ''lifetime'' - a change is cheap insurance), ~EUR 60-120. The clutch is a condition-based wear item, not a scheduled service: ~EUR 400-900, or ~EUR 700-1,300 with a dual-mass flywheel. Otherwise nothing to schedule.' where code = 'generic:4-speed Manual';
update transmission_units set maintenance_note = 'Near-zero scheduled maintenance. Reducer oil is often ''lifetime''; where a change is specified it''s ~every 100-150k km, ~EUR 80-150. No clutch, filter or converter. Any real drivetrain cost is motor/inverter electronics, not the gear.' where code = 'generic:Single-speed EV';
update transmission_units set maintenance_note = 'Near-zero scheduled maintenance. Reducer oil is often ''lifetime''; where a change is specified it''s ~every 100-150k km, ~EUR 80-150. No clutch, filter or converter. Any real drivetrain cost is motor/inverter electronics, not the gear.' where code = 'generic:Single-speed RWD';
update transmission_units set maintenance_note = 'Near-zero scheduled maintenance on the two reducers. Optional reducer-oil change ~every 100-150k km if specified, ~EUR 120-220 for both. No clutch/converter. Costs sit in motor/inverter electronics.' where code = 'generic:Single-speed AWD dual motor';
update transmission_units set maintenance_note = 'Near-zero scheduled maintenance on the two reducers. Optional reducer-oil change ~every 100-150k km if specified, ~EUR 120-220 for both. No clutch/converter. Costs sit in motor/inverter electronics.' where code = 'generic:Single-speed EV (dual motor)';
update transmission_units set maintenance_note = 'Reducer is near-maintenance-free (optional oil ~every 100-150k km, ~EUR 80-150). But there''s a petrol engine acting as a generator - it needs its normal oil/filter service (~every 15-20k km, ~EUR 60-150) and the usual engine upkeep.' where code = 'generic:e-Power Fixed Ratio';
update transmission_units set maintenance_note = 'Reducers are near-maintenance-free (optional oil ~every 100-150k km, ~EUR 120-220). The petrol generator engine still needs its normal oil/service (~every 15-20k km, ~EUR 60-150) plus usual engine upkeep.' where code = 'generic:2-speed rear + single-speed front';
update transmission_units set maintenance_note = 'Near-zero scheduled maintenance. Reducer oil is often ''lifetime''; where a change is specified it''s ~every 100-150k km, ~EUR 80-150. No clutch, filter or converter. Any real drivetrain cost is motor/inverter electronics, not the gear.' where code = 'generic:Single-speed EV (i5)';
update transmission_units set maintenance_note = 'Ignore the ''sealed for life'' label: full oil + filter (pan) change ~every 80-100k km or 8 years, ~EUR 250-450 at a specialist with genuine ZF fluid/kit. No clutch. Do this and the unit is essentially bulletproof; skip it and you get valve-body wear/harsh shifts.' where code = 'ZF 8HP';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-80k km (don''t trust ''lifetime''), ~EUR 200-380. Mostly a fluid-discipline unit; jerky low-speed shifts are usually software, not a service item. No clutch.' where code = 'Aisin 8AT';
update transmission_units set maintenance_note = 'ATF change ~every 60-90k km, ~EUR 150-300 (some have no serviceable filter). Very durable; fluid is basically the only scheduled item. No clutch.' where code = 'Aisin 6AT';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-100k km (most are wrongly sold as ''lifetime''), ~EUR 200-400. Generally the most durable auto type; fluid is the main scheduled cost. No clutch.' where code = 'generic:8-speed Torque converter';
update transmission_units set maintenance_note = 'ATF change ~every 60-80k km, ~EUR 180-320. Low-speed shudder is usually a fluid/TCM-software fix rather than mechanical. Durable otherwise; fluid is the main item.' where code = 'Mazda Skyactiv-Drive 6AT';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-80k km (MB''s longer ~125k figure is optimistic), ~EUR 300-500 with genuine fluid. Lock-up shudder is often addressed with a fluid change/software. No clutch.' where code = 'Mercedes 9G-TRONIC';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-80k km, ~EUR 250-450. Most complaints are shift-quality/software (recalibrations) rather than service items; some mechanical failures in Jeep/LR use. Keep fluid fresh.' where code = 'ZF 9HP';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-90k km (not ''lifetime''), ~EUR 180-350. Durable type; fluid is the main scheduled cost, plus occasional lock-up shudder addressed by fresh fluid/software.' where code = 'generic:6-speed Torque converter';
update transmission_units set maintenance_note = 'ATF change ~every 60-90k km, ~EUR 180-330. Solid in-house unit; harsh shifts are usually a software update, not a service. Fluid is the main item.' where code = 'Hyundai 8AT';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-80k km, ~EUR 250-450. The classic cost is the conductor plate / 13-pin valve-body connector (~EUR 500-900 if it fails, causing limp mode) - fresh fluid helps delay it. Budget for the conductor plate on a high-km 722.9.' where code = 'Mercedes 7G-TRONIC (722.9)';
update transmission_units set maintenance_note = 'ATF change ~every 60-90k km, ~EUR 150-280. Old, simple, durable design; fluid is the only real scheduled item. No clutch.' where code = 'Aisin 4AT';
update transmission_units set maintenance_note = 'ATF + filter change ~every 80-100k km, ~EUR 250-450 (large fluid volume). Early harsh-shift/clunk issues are valve-body/solenoid TSBs and software rather than routine service - check updates were done. Durable hardware otherwise.' where code = 'Ford 10R80 (10-speed)';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-90k km, ~EUR 200-350. Conventional stepped auto (unlike Jatco''s CVTs); fluid is the main scheduled cost. No clutch.' where code = 'Jatco 7AT';
update transmission_units set maintenance_note = 'ATF + filter (pan) change ~every 80-100k km, ~EUR 250-400 - not ''lifetime.'' Budget for the known mechatronic sleeve/adapter seal leak (~EUR 300-600 to reseal) which causes harsh shifts/limp mode if ignored. Fresh fluid + that seal keep it healthy.' where code = 'ZF 6HP';
update transmission_units set maintenance_note = 'ATF + filter change ~every 80-100k km, ~EUR 250-450 (large volume). Sister to the Ford 10R80; early shift-quality issues are TSB/software, not service. Durable otherwise.' where code = 'GM 10L80 (10-speed)';
update transmission_units set maintenance_note = 'ATF + filter change ~every 80-100k km, ~EUR 250-450 (large fluid volume). Durable type; fluid is the main scheduled cost. Not a ''lifetime'' fill.' where code = 'generic:10-speed Torque converter';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-90k km, ~EUR 220-420. Durable type; fluid is the main item, plus occasional lock-up shudder addressed by fresh fluid/software.' where code = 'generic:9-speed Torque converter';
update transmission_units set maintenance_note = 'ATF + filter change ~every 60-90k km, ~EUR 200-380. Durable type; fluid is the main scheduled cost. Treat as service-required, not ''lifetime.''' where code = 'generic:7-speed Torque converter';
